async function firecrawlHealthCheck(): Promise<{
  status: HealthStatus;
  details: Record<string, any>;
}> {
  const checks = {
    api: await checkApiConnectivity(),
    circuitBreaker: firecrawlBreaker.stats(),
    dlqSize: deadLetterQueue.size(),
