function getServiceAdapter(): ServiceAdapter {
  const groqPercentage = getFeatureFlag('groq_migration_percentage');

  if (Math.random() * 100 < groqPercentage) {
    return new GroqAdapter();
  }

  return new LegacyAdapter();
}
```

