// src/cost/usage-tracker.ts
interface UsageBudget {
  dailyQueryLimit: number;
  dailyDeepConsultLimit: number;
  monthlyBudget: number;
  alertThreshold: number; // 0-1
}

interface UsageRecord {
  queries: number;
